import CoachingPresentation
import Foundation

/// Reads the committed CoachingCore captures (`CoachingPresentation/Tests/.../Fixtures`, generated by `Facade/capture-fixtures.mjs`). The parallel-
/// phase providers ONLY replay these files: no response JSON is written by hand (handoff C §4). The app bundles the directory as a folder
/// reference; tests read it from the repository.
public struct FixtureStore: Sendable {
    public let directory: URL
    public init(directory: URL) { self.directory = directory }

    /// The app bundle's copy (folder reference `Fixtures`), if present.
    public static var bundled: FixtureStore? {
        Bundle.main.url(forResource: "Fixtures", withExtension: nil).map(FixtureStore.init(directory:))
    }

    public enum Failure: Error, Equatable { case missing(String), notAnObject(String), noKey(String, String) }

    /// The raw JSON object of `name.json`.
    public func object(_ name: String) throws -> [String: Any] {
        let url = directory.appendingPathComponent(name + ".json")
        guard let data = try? Data(contentsOf: url) else { throw Failure.missing(name) }
        guard let obj = try JSONSerialization.jsonObject(with: data) as? [String: Any] else { throw Failure.notAnObject(name) }
        return obj
    }

    /// Decode `name.json`, optionally at one top-level key.
    public func decode<T: Decodable>(_ type: T.Type, _ name: String, at key: String? = nil) throws -> T {
        var obj: Any = try object(name)
        if let key {
            guard let v = (obj as? [String: Any])?[key] else { throw Failure.noKey(name, key) }
            obj = v
        }
        return try JSONDecoder().decode(T.self, from: JSONSerialization.data(withJSONObject: obj, options: [.fragmentsAllowed]))
    }

    /// `{ok:false, error, state}` captures as the port's failure.
    public func error(_ name: String) throws -> BoundaryError { try decode(BoundaryError.self, name, at: "error") }

    /// Every fixture file named by `INDEX.json`.
    public func indexedFiles() throws -> [String] {
        let index = try object("INDEX")
        return ((index["files"] as? [[String: Any]]) ?? []).compactMap { ($0["file"] as? String)?.replacingOccurrences(of: ".json", with: "") }
    }
}
